type BookingStep =
  | 'searching'
  | 'choosing'
  | 'holding'
  | 'details'
  | 'confirming'
  | 'confirmed'
  | 'hold-expired'
  | 'price-changed'
  | 'sold-out';

interface LocalDateTime {
  date: string;
  time: string;
  timeZone: string;
}

interface RentalSearch {
  pickupBranchId: string;
  returnBranchId: string;
  pickupAt: LocalDateTime;
  returnAt: LocalDateTime;
  driverAge: number;
}

interface PriceLine {
  code: string;
  label: string;
  amountMinor: number;
}

interface VehicleOffer {
  offerId: string;
  searchId: string;
  vehicleClass: string;
  exampleModel: string;
  rentalDays: number;
  currency: string;
  lines: PriceLine[];
  totalMinor: number;
  expiresAt: string;
}

interface VehicleHold {
  holdId: string;
  offerId: string;
  idempotencyKey: string;
  totalMinor: number;
  expiresAt: string;
  extensionsLeft: number;
  status: 'active' | 'expired' | 'released' | 'converted';
}

interface DriverDetails {
  firstName: string;
  lastName: string;
  email: string;
  licenseCountry: string;
}

interface BookingDraft {
  search: RentalSearch;
  selectedOfferId: string | null;
  extras: string[];
  driver: DriverDetails | null;
  hold: VehicleHold | null;
  step: BookingStep;
}
